          M5_LOGD("Core2: Disconnecting from different network: %s", current_ssid.c_str());
          WiFi.disconnect();
          delay(200);
        }
      }
      #endif
      password ? WiFi.begin(ssid, password) : WiFi.begin(ssid);
      wait_for_connection(3000);
      update_active();
      return wifi_connected();
  }
}

