19	bool ApiConnector::activate(bool retry) {
20	  if (WiFiWrapper_i.wifi_connected()) {
21	    return true;
22	  }
23	  if (retry && millis() - _last_retry < RETRY_TIMEOUT) {
24	    return false;
25	  }
26	  _last_retry = millis();
27	
28	  WiFiWrapper_i.connect_wifi(_config.get_active_wifi_ssid(), _config.get_active_wifi_password(), !retry);
29	
30	  return WiFi.isConnected();
31	}
