66	int8_t ApiConnector::handle_produced_work(const worker_map_t& workers) {
67	  if (!_config.get_fixed_device_id()) {
68	    // Cant even send anything, because there is an invalid id
69	    return e_handler_idle;
70	  }
71	
72	  const auto& log_aggregator = workers.worker<LogAggregator>(k_worker_log_aggregator);
73	  const auto& log_data = log_aggregator->get_data();
74	
75	  if (!log_aggregator->is_fresh()) {
76	    // No fresh data
77	    return e_handler_idle;
78	  }
79	
80	  if (!log_data.valid()) {
81	    // data not valid (either gm or gps)
82	    return e_handler_idle;
83	  }
84	
85	  if (!time_to_send(log_data.in_fixed_range, log_data.cpm > _config.get_alert_threshold())) {
86	    // Not time to send yet
87	    return e_handler_idle;
88	  }
89	
90	  if (!WiFi.isConnected() && !activate(true)) {
91	    M5_LOGD("Unable to send, lost connection");
92	    return e_api_reporter_error_not_connected;
93	  }
94	
95	  if (!reading_to_json(log_data,_payload)) {
96	    return e_api_reporter_error_to_json;
97	  }
98	
99	  M5_LOGD("Starting task to send data to API...");
100	  return start_task("api_send", 2048 * 4, 3);
101	}
