103	bool ApiConnector::reading_to_json(const DataLine& line, char* out) {
104	  auto result = sprintf(
105	      out,
106	      "{\"captured_at\":\"%s\","
107	      "\"device_id\":%d,"
108	      "\"value\":%u,"
109	      "\"unit\":\"cpm\","
110	      "\"height\":%0.6f,"
111	      "\"latitude\":%0.6f,"
112	      "\"longitude\":%0.6f}",
113	      line.timestamp,
114	      _config.get_fixed_device_id(),
115	      line.cpm,
116	      line.in_fixed_range ? 0 : line.latitude,  // TODO: fixed location altitude
117	      line.in_fixed_range ? _config.get_fixed_latitude() : line.latitude,
118	      line.in_fixed_range ? _config.get_fixed_longitude() : line.longitude);
119	  return result > 0;
