126	int8_t ApiConnector::handle_async() {
127	  const unsigned long time_at_send = millis();
128	
129	  char url[100];
130	  sprintf(url, "%s?api_key=%s&", TTSERVE_MEASUREMENTS_ENDPOINT, _config.get_api_key());
131	
132	  //Specify destination for HTTP request
133	  if (!_http_client.begin(url)) {
134	    M5_LOGD("Unable to begin url connection");
135	    _http_client.end(); //Free resources
136	    return e_api_reporter_error_remote_not_available;
137	  }
138	
139	  char content_length[5];
140	
141	  sprintf(content_length, "%d", strlen(_payload));
142	
143	  _http_client.setUserAgent(HEADER_API_USER_AGENT);
144	  _http_client.addHeader("Host", TTSERVE_HOST);
145	  _http_client.addHeader("Content-Type", "application/json");
146	  _http_client.addHeader("Content-Length", content_length);
147	
148	  int httpResponseCode = _http_client.POST(_payload);
149	
150	  String response = _http_client.getString();
151	  M5_LOGD("POST complete, response (%d):\n%s\n", httpResponseCode, response.c_str());
152	  _http_client.end(); //Free resources
153	
154	  // TODO: Check response measurement ID
155	
156	  WiFiWrapper_i.update_active();
157	  _last_post = time_at_send;
158	
159	  switch (httpResponseCode) {
160	    case 200 ... 204:
161	      ++_post_count;
162	      return e_api_reporter_send_success;
163	    case 400:
164	      return e_api_reporter_error_server_rejected_post_400;
165	    case 401:
166	      return e_api_reporter_error_server_rejected_post_401;
167	    case 403:
168	      return e_api_reporter_error_server_rejected_post_403;
169	    case 500 ... 599:
170	      return e_api_reporter_error_server_rejected_post_5xx;
171	    default:
172	      return e_api_reporter_error_remote_not_available;
173	  }
174	}

