12	// Bounded wait for WiFi.status() to reach WL_CONNECTED after begin()/reconnect(),
13	// instead of a single delay(100) + give-up.
14	static bool wait_for_connection(uint32_t timeout_ms) {
15	  uint32_t start = millis();
16	  while (millis() - start < timeout_ms) {
17	    if (WiFi.status() == WL_CONNECTED) {
18	      return true;
19	    }
20	    delay(100);
21	  }
22	  return WiFi.status() == WL_CONNECTED;
23	}
