50	bool WiFiWrapper::connect_wifi(const char* ssid, const char* password, bool first_time, bool wait_for_result) {
51	  switch(WiFi.status()) {
52	    case WL_CONNECTED:
53	      return true;
54	    case WL_CONNECT_FAILED:
55	      if (first_time) {
56	        M5_LOGD("WiFi connector: Trying to reconnect to wifi...");
57	        #ifndef CONFIG_IDF_TARGET_ESP32S3
58	        // On Core2, disconnect and clear state before reconnecting
59	        WiFi.disconnect(true);
60	        delay(50);
61	        #endif
62	        WiFi.reconnect();
63	        if (wait_for_result) {
64	          wait_for_connection(3000);
65	        }
66	        update_active();
67	        return wifi_connected();
68	      }
69	      return false;
70	    case WL_DISCONNECTED:
71	      M5_LOGD("WiFi connector: Trying to reconnect to wifi...");
72	      #ifndef CONFIG_IDF_TARGET_ESP32S3
73	      // On Core2, disconnect and clear state before reconnecting
74	      WiFi.disconnect(true);
75	      delay(50);
76	      #endif
77	      WiFi.reconnect();
78	      if (wait_for_result) {
79	        wait_for_connection(3000);
80	      }
81	      update_active();
82	      return wifi_connected();
83	    default:
84	      M5_LOGD("WiFi connector: Trying to connect to wifi (%s:%s)...", ssid, password);
85	      #ifndef CONFIG_IDF_TARGET_ESP32S3
86	      // On Core2, ensure WiFi is properly started before connecting
87	      uint8_t current_status = WiFi.status();
88	      M5_LOGD("Core2: Current WiFi status before connect: %d", current_status);
89	
90	      if (current_status == 255) {
91	        // WiFi is completely uninitialized - initialize and start it
92	        M5_LOGD("Core2: WiFi uninitialized (status 255), initializing and starting WiFi");
93	        WiFi.mode(WIFI_STA);
94	        delay(100);
95	        esp_wifi_start();  // Explicitly start the WiFi radio
96	        delay(200);
97	        current_status = WiFi.status();
98	        M5_LOGD("Core2: WiFi started, status now: %d", current_status);
99	      } else if (current_status == WL_DISCONNECTED || current_status == WL_IDLE_STATUS) {
100	        // WiFi is initialized but disconnected - safe to restart
101	        M5_LOGD("Core2: Restarting WiFi radio from status %d", current_status);
102	        esp_wifi_stop();  // Ensure it's fully stopped
103	        delay(100);
104	        esp_wifi_start(); // Restart it
105	        delay(200);
106	        current_status = WiFi.status();
107	        M5_LOGD("Core2: WiFi status after restart: %d", current_status);
108	      } else if (current_status == WL_CONNECTED) {
109	        // Only disconnect if currently connected to a different network
110	        String current_ssid = WiFi.SSID();
111	        if (current_ssid != ssid) {
112	          M5_LOGD("Core2: Disconnecting from different network: %s", current_ssid.c_str());
113	          WiFi.disconnect();
114	          delay(200);
115	        }
116	      }
117	      #endif
118	      password ? WiFi.begin(ssid, password) : WiFi.begin(ssid);
119	      if (wait_for_result) {
120	        wait_for_connection(3000);
121	      }
122	      update_active();
123	      return wifi_connected();
124	  }
125	}
