147	bool WiFiWrapper::start_ap_server(uint16_t device_id, const char* password) {
148	  M5_LOGD("Starting WiFi AP server...");
149	
150	  wifi_mode_t current_mode = WiFi.getMode();
151	  M5_LOGD("Current WiFi mode: %d", current_mode);
152	
153	  #ifndef CONFIG_IDF_TARGET_ESP32S3
154	  // On Core2, we need to ensure WiFi is properly initialized and reset before AP
155	  // to avoid buffer allocation errors during mode operations
156	  if (current_mode == WIFI_MODE_NULL) {
157	    // WiFi is completely uninitialized - initialize it first
158	    M5_LOGD("Core2: WiFi uninitialized, initializing to STA mode first");
159	    WiFi.mode(WIFI_STA);
160	    delay(200);
161	    current_mode = WiFi.getMode();
162	    M5_LOGD("Core2: WiFi initialized, mode now: %d", current_mode);
163	  }
164	
165	  // Now do a full reset regardless of previous state to ensure clean AP initialization
166	  if (current_mode == WIFI_STA || current_mode == WIFI_AP_STA) {
167	    M5_LOGD("Core2: Fully resetting WiFi from mode %d to AP mode", current_mode);
168	    WiFi.disconnect(false);
169	    delay(200);
170	
171	    // Fully stop WiFi to reset buffers
172	    esp_wifi_stop();
173	    delay(300);
174	
175	    // Restart WiFi
176	    esp_wifi_start();
177	    delay(300);
178	
179	    M5_LOGD("Core2: WiFi reset complete, mode now: %d", WiFi.getMode());
180	  }
181	  #else
182	  // CoreS3: Can use standard disconnect
183	  if (current_mode != WIFI_MODE_NULL && current_mode != WIFI_AP) {
184	    WiFi.disconnect(true);
185	    delay(200);
186	  }
187	  #endif
188	
189	  // softAP() will now initialize in AP mode with fresh buffers
190	  char host_ssid[20];
191	  sprintf(host_ssid, ACCESS_POINT_SSID, device_id);
192	  M5_LOGD("Starting AP with SSID: %s", host_ssid);
193	  WiFi.softAP(host_ssid, password);
194	  WiFi.softAPsetHostname(host_ssid);
195	  delay(100);
196	
