34	  if (WiFiWrapper_i.wifi_connected()) {
35	    return;
36	  }
37	  if (!_config.get_fixed_device_id()) {
38	    // No valid device id configured, nothing to upload, leave wifi alone
39	    return;
40	  }
41	  if (WiFiWrapper_i.ap_server_up()) {
42	    // User is on the AP config screen, don't fight it
43	    return;
44	  }
45	  if (WiFiWrapper_i.consume_disconnect_event()) {
46	    // A disconnect event fired: skip the backoff and retry now
47	    M5_LOGD("WiFi connector: disconnect event detected, retrying now");
48	    _last_retry = 0;
49	  }
50	  if (millis() - _last_retry < RETRY_TIMEOUT) {
51	    return;
52	  }
53	  _last_retry = millis();
54	
55	  // Non-blocking: kick off the attempt and let the next call(s) observe the
56	  // result. Never wait here — this runs every loop() iteration and must not
57	  // stall touch/button polling (M5.update()), which is what freezes the
58	  // screen (Core2 menu buttons, CoreS3 screensaver wake) during a failed
