69	  if (!_config.get_fixed_device_id()) {
70	    // Cant even send anything, because there is an invalid id
71	    return e_handler_idle;
72	  }
73	
74	  const auto& log_aggregator = workers.worker<LogAggregator>(k_worker_log_aggregator);
75	  const auto& log_data = log_aggregator->get_data();
76	
77	  if (!log_aggregator->is_fresh()) {
78	    // No fresh data
79	    return e_handler_idle;
80	  }
81	
82	  if (!log_data.valid()) {
83	    // data not valid (either gm or gps)
84	    return e_handler_idle;
85	  }
86	
87	  if (!time_to_send(log_data.in_fixed_range, log_data.cpm > _config.get_alert_threshold())) {
88	    // Not time to send yet
89	    return e_handler_idle;
90	  }
91	
92	  if (!WiFi.isConnected() && !activate(true)) {
93	    M5_LOGD("Unable to send, lost connection");
94	    return e_api_reporter_error_not_connected;
95	  }
96	
97	  if (!reading_to_json(log_data,_payload)) {
98	    return e_api_reporter_error_to_json;
99	  }
100	
101	  M5_LOGD("Starting task to send data to API...");
