117	      line.cpm,
118	      line.in_fixed_range ? 0 : line.latitude,  // TODO: fixed location altitude
119	      line.in_fixed_range ? _config.get_fixed_latitude() : line.latitude,
120	      line.in_fixed_range ? _config.get_fixed_longitude() : line.longitude);
