136	    M5_LOGD("Unable to begin url connection");
137	    _http_client.end(); //Free resources
138	    return e_api_reporter_error_remote_not_available;
139	  }
140	
141	  char content_length[5];
142	
143	  sprintf(content_length, "%d", strlen(_payload));
144	
145	  _http_client.setUserAgent(HEADER_API_USER_AGENT);
146	  _http_client.addHeader("Host", TTSERVE_HOST);
147	  _http_client.addHeader("Content-Type", "application/json");
148	  _http_client.addHeader("Content-Length", content_length);
149	
150	  int httpResponseCode = _http_client.POST(_payload);
151	
152	  String response = _http_client.getString();
153	  M5_LOGD("POST complete, response (%d):\n%s\n", httpResponseCode, response.c_str());
154	  _http_client.end(); //Free resources
155	
156	  // TODO: Check response measurement ID
157	
158	  WiFiWrapper_i.update_active();
159	  _last_post = time_at_send;
160	
161	  switch (httpResponseCode) {
162	    case 200 ... 204:
163	      ++_post_count;
164	      return e_api_reporter_send_success;
165	    case 400:
166	      return e_api_reporter_error_server_rejected_post_400;
167	    case 401:
168	      return e_api_reporter_error_server_rejected_post_401;
169	    case 403:
170	      return e_api_reporter_error_server_rejected_post_403;
171	    case 500 ... 599:
172	      return e_api_reporter_error_server_rejected_post_5xx;
173	    default:
174	      return e_api_reporter_error_remote_not_available;
